using System;using System.Windows.Forms;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.Linq;using System.Runtime.InteropServices;
public sealed partial class MillDungeonScene {
 bool[] sight,opaque;int visualKey=Int32.MinValue;Bitmap shadeMap,warmMap;byte[] shadePixels,warmPixels;
 int VisualKey(){unchecked{int key=State.floor*397+State.playerX*31+State.playerY;foreach(var p in Floor.props)if(p.kind=="lamp"||p.kind=="door")key=key*31+p.state+p.x*3+p.y;return key;}}
 void EnsureVisuals(){int key=VisualKey();if(sight!=null&&key==visualKey)return;visualKey=key;opaque=new bool[Floor.tiles.Length];sight=new bool[Floor.tiles.Length];for(int y=0;y<Floor.height;y++)for(int x=0;x<Floor.width;x++)opaque[y*Floor.width+x]=Floor.Tile(x,y)==0;foreach(var p in Floor.props.Where(p=>p.kind=="door"&&p.state==0))for(int y=p.y;y<p.y+p.h;y++)for(int x=p.x;x<p.x+p.w;x++)opaque[y*Floor.width+x]=true;
  for(int y=State.playerY-8;y<=State.playerY+8;y++)for(int x=State.playerX-8;x<=State.playerX+8;x++)if(Floor.Inside(x,y)&&(x-State.playerX)*(x-State.playerX)+(y-State.playerY)*(y-State.playerY)<=64&&RayClear(State.playerX,State.playerY,x,y)){sight[y*Floor.width+x]=true;Floor.seen[y*Floor.width+x]=true;}
  BuildIllumination();
 }
 bool RayClear(int x,int y,int tx,int ty){int dx=Math.Abs(tx-x),dy=-Math.Abs(ty-y),sx=x<tx?1:-1,sy=y<ty?1:-1,err=dx+dy;while(x!=tx||y!=ty){if(!Floor.Inside(x,y)||opaque[y*Floor.width+x])return false;int e2=err*2,nx=x,ny=y;if(e2>=dy){err+=dy;nx+=sx;}if(e2<=dx){err+=dx;ny+=sy;}if(nx!=x&&ny!=y&&Floor.Inside(nx,y)&&Floor.Inside(x,ny)&&opaque[y*Floor.width+nx]&&opaque[ny*Floor.width+x])return false;x=nx;y=ny;}return true;}
 bool InSight(int x,int y){return Floor.Inside(x,y)&&sight!=null&&sight[y*Floor.width+x];}
 bool PropInSight(MillProp p){for(int y=p.y;y<p.y+p.h;y++)for(int x=p.x;x<p.x+p.w;x++)if(InSight(x,y))return true;return false;}
 float Ambient(string type){switch(type){case "mill":return .64f;case "entry":return .55f;case "guard":return .61f;case "ledger":return .58f;case "grain":return .38f;case "wheel":case "drain":case "terminal":return .35f;case "cache":return .29f;case "stairs":case "cellar":return .34f;default:return .39f;}}
 void BuildIllumination(){int fw=Floor.width,fh=Floor.height;float[] light=new float[fw*fh],warm=new float[fw*fh];for(int y=0;y<fh;y++)for(int x=0;x<fw;x++){var r=Floor.rooms.FirstOrDefault(r0=>r0.Contains(x,y));light[y*fw+x]=Ambient(r==null?"":r.type)-(State.floor==1?.035f:0);}
  foreach(var lamp in Floor.props.Where(p=>p.kind=="lamp"&&p.state==0)){const float radius=5.2f;for(int y=lamp.y-5;y<=lamp.y+5;y++)for(int x=lamp.x-5;x<=lamp.x+5;x++)if(Floor.Inside(x,y)){float dx=x-lamp.x,dy=y-lamp.y,dist=(float)Math.Sqrt(dx*dx+dy*dy);if(dist>radius||!RayClear(lamp.x,lamp.y,x,y))continue;float value=1-dist/radius;light[y*fw+x]+=.66f*value*value;warm[y*fw+x]+=.9f*value*value;}}
  int w=fw*8,h=fh*8;if(shadeMap==null){shadeMap=new Bitmap(w,h,PixelFormat.Format32bppArgb);warmMap=new Bitmap(w,h,PixelFormat.Format32bppArgb);shadePixels=new byte[w*h*4];warmPixels=new byte[w*h*4];}
  for(int py=0;py<h;py++)for(int px=0;px<w;px++){float gx=px/8f-.5f,gy=py/8f-.5f;int x0=Math.Max(0,Math.Min(fw-1,(int)Math.Floor(gx))),y0=Math.Max(0,Math.Min(fh-1,(int)Math.Floor(gy)));int x1=Math.Min(fw-1,x0+1),y1=Math.Min(fh-1,y0+1);float fx=Math.Max(0,gx-x0),fy=Math.Max(0,gy-y0);float a=Mix(light[y0*fw+x0],light[y0*fw+x1],fx),b=Mix(light[y1*fw+x0],light[y1*fw+x1],fx),l=Mix(a,b,fy);float wa=Mix(warm[y0*fw+x0],warm[y0*fw+x1],fx),wb=Mix(warm[y1*fw+x0],warm[y1*fw+x1],fx),warmth=Mix(wa,wb,fy);
   float dx=px/8f-State.playerX-.5f,dy=py/8f-State.playerY-.5f,dist=(float)Math.Sqrt(dx*dx+dy*dy);l=Math.Max(l,.59f-Math.Max(0,dist-1.4f)*.085f);int alpha=(int)(255*(1-Math.Min(1,Math.Max(.12f,l))));alpha=Math.Max(alpha,(int)(Math.Min(1,Math.Max(0,(dist-5.8f)/2.3f))*250));int i=(py*w+px)*4;shadePixels[i]=23;shadePixels[i+1]=13;shadePixels[i+2]=8;shadePixels[i+3]=(byte)Math.Min(255,alpha);warmPixels[i]=65;warmPixels[i+1]=171;warmPixels[i+2]=255;warmPixels[i+3]=(byte)Math.Min(32,warmth*26);
  }WritePixels(shadeMap,shadePixels);WritePixels(warmMap,warmPixels);
 }
 static float Mix(float a,float b,float t){return a+(b-a)*t;}
 static void WritePixels(Bitmap bitmap,byte[] bytes){var data=bitmap.LockBits(new Rectangle(0,0,bitmap.Width,bitmap.Height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{Marshal.Copy(bytes,0,data.Scan0,bytes.Length);}finally{bitmap.UnlockBits(data);}}
 void DrawIllumination(Graphics g){var rect=new Rectangle(0,0,Floor.width*32,Floor.height*32);g.DrawImage(warmMap,rect);g.DrawImage(shadeMap,rect);}
 void DisposeVisuals(){if(shadeMap!=null)shadeMap.Dispose();if(warmMap!=null)warmMap.Dispose();}
 void DrawFurnitureShadow(Graphics g,MillProp p){if(p.kind=="ground"||p.kind=="lamp"||p.kind=="door")return;int x=p.x*32,y=(p.y+p.h)*32;using(var ink=new SolidBrush(Color.FromArgb(74,9,9,13)))g.FillPolygon(ink,new[]{new Point(x+3,y-7),new Point(x+p.w*32-3,y-7),new Point(x+p.w*32+8,y+4),new Point(x+9,y+4)});}
 void DrawDoorFrame(Graphics g,MillProp p){var stone=ImageFor("02-structure-01");int x=p.x*32,y=p.y*32;
  using(var ink=new SolidBrush(Color.FromArgb(100,6,8,11)))g.FillRectangle(ink,x-3,y-8,p.w*32+6,p.h*32+15);
  if(p.art!="02-structure-25"){g.DrawImage(stone,new Rectangle(x-8,y-20,8,52),new Rectangle(9,15,7,38),GraphicsUnit.Pixel);g.DrawImage(stone,new Rectangle(x+p.w*32,y-20,8,52),new Rectangle(9,15,7,38),GraphicsUnit.Pixel);g.DrawImage(stone,new Rectangle(x-8,y-22,p.w*32+16,9),new Rectangle(16,18,32,7),GraphicsUnit.Pixel);}else {g.DrawImage(stone,new Rectangle(x-6,y-10,44,9),new Rectangle(16,18,32,7),GraphicsUnit.Pixel);g.DrawImage(stone,new Rectangle(x-6,y+p.h*32-3,44,9),new Rectangle(16,18,32,7),GraphicsUnit.Pixel);}
 }
 void DrawFloorDetail(Graphics g,int x,int y,string type,uint hash){bool wet=type=="wheel"||type=="drain"||type=="terminal"||type=="cellar";bool wall=Floor.Tile(x-1,y)==0||Floor.Tile(x+1,y)==0||Floor.Tile(x,y-1)==0||Floor.Tile(x,y+1)==0;
  string art=null;if(wet&&wall&&hash%5==0)art="06-effects-49";else if(type=="mill"&&hash%9==0)art="03-containers-39";else if(type=="grain"&&hash%11==0)art="03-containers-37";else if((type=="tools"||type=="cache")&&hash%17==0)art="06-effects-33";
  if(art!=null){if(type=="mill"||type=="grain")g.DrawImage(ImageFor(art),new Rectangle(x*32+2,y*32+15,28,14),new Rectangle(0,34,64,30),GraphicsUnit.Pixel);else g.DrawImage(ImageFor(art),new Rectangle(x*32+5,y*32+12,22,18));}
  if(wet&&Floor.Tile(x,y)!=3){bool near=Floor.Tile(x-1,y)==3||Floor.Tile(x+1,y)==3||Floor.Tile(x,y-1)==3||Floor.Tile(x,y+1)==3;if(near)using(var ink=new SolidBrush(Color.FromArgb(46,23,50,58)))g.FillRectangle(ink,x*32,y*32,32,32);}
  if(Floor.Tile(x,y)==2){using(var edge=new SolidBrush(Color.FromArgb(82,58,37))){if(Floor.Tile(x,y-1)!=2&&Floor.Tile(x,y-1)>0)g.FillRectangle(edge,x*32,y*32,32,5);if(Floor.Tile(x-1,y)!=2&&Floor.Tile(x-1,y)>0)g.FillRectangle(edge,x*32,y*32,5,32);}}
 }
 void DrawExplorationAtlas(Graphics g){var r=new Rectangle(35,88,Math.Max(100,Width-70),Math.Max(100,Height-176));Panel(g,r);Text(g,"已探索地图 · "+(State.floor==0?"上层":"地下层")+"    M 返回探索",new Rectangle(r.X+16,r.Y+10,r.Width-32,34),13,GuildChrome.Ivory);
  int legend=Width>=1000?270:190;float k=Math.Min((r.Width-legend-35)/(float)Floor.width,(r.Height-80)/(float)Floor.height);float ox=r.X+18+(r.Width-legend-35-Floor.width*k)/2,oy=r.Y+54;
  for(int y=0;y<Floor.height;y++)for(int x=0;x<Floor.width;x++)if(Known(x,y)){int t=Floor.Tile(x,y);Color ink=t==3?Color.FromArgb(52,112,130):t==2||t==4?Color.FromArgb(143,113,72):Floor.Wall(x,y)>0?Color.FromArgb(48,67,65):Color.FromArgb(117,126,111);if(t>0||Floor.Wall(x,y)>0)using(var b=new SolidBrush(ink))g.FillRectangle(b,ox+x*k,oy+y*k,Math.Max(1,k-.3f),Math.Max(1,k-.3f));}
  foreach(var p in Floor.props.Where(p=>Known(p.x,p.y)&&(p.kind=="door"||p.kind=="up"||p.kind=="down"||p.kind=="goal"||p.kind=="exit")))using(var b=new SolidBrush(p.kind=="door"?Color.FromArgb(182,148,83):Color.FromArgb(142,220,191)))g.FillRectangle(b,ox+p.x*k,oy+p.y*k,Math.Max(3,p.w*k),Math.Max(3,p.h*k));
  using(var b=new SolidBrush(Color.FromArgb(253,222,127)))g.FillEllipse(b,ox+(State.playerX+.5f)*k-4,oy+(State.playerY+.5f)*k-4,8,8);
  int lx=r.Right-legend,ly=r.Y+56,rowHeight=Math.Min(39,Math.Max(22,(r.Height-165)/8));Text(g,"分区记录",new Rectangle(lx,ly,legend-14,30),12,GuildChrome.Ivory);ly+=38;foreach(var room in Floor.rooms){bool found=Known(room.CenterX,room.CenterY);Text(g,(room.id+1)+"  "+(found?room.name:"未探索区域"),new Rectangle(lx,ly,legend-16,rowHeight),Width>=1000?10:9,found?GuildChrome.Ivory:Color.FromArgb(100,122,113));ly+=rowHeight;}foreach(var label in new[]{"金点：当前位置","浅绿：楼梯 / 出口","棕色：已发现门洞"}){Text(g,label,new Rectangle(lx,ly+6,legend-16,18),9,Color.FromArgb(151,174,152));ly+=18;}
 }
 void DrawMillStoneTop(Graphics g,MillProp p,RectangleF bounds){g.DrawImage(ImageFor("05-machinery-11"),new RectangleF(bounds.X+bounds.Width*.06f,bounds.Y+bounds.Height*.32f,bounds.Width*.88f,bounds.Height*.65f));}
 void DrawWheelSpray(Graphics g,MillProp p,RectangleF b){if(!State.waterOn)return;string art="06-effects-"+(61+(int)(animation*8)%4).ToString("00");g.DrawImage(ImageFor(art),new RectangleF(b.X+b.Width*.12f,b.Bottom-30,b.Width*.78f,36));}
